export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const safeURL=u=>{try{const x=new URL(u);return ['https:','http:'].includes(x.protocol)?x.href:''}catch{return ''}};
const beijingTime=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hourCycle:'h23'});
export const stamp=s=>{if(typeof s!=='string'||!s)return '';if(/^\d{4}-\d{2}-\d{2}$/.test(s)){const [,month,day]=s.split('-');return `${Number(month)} 月 ${Number(day)} 日`;}if(!/T.*(?:Z|[+-]\d{2}:\d{2})$/.test(s))return '';const date=new Date(s);if(!Number.isFinite(date.getTime()))return '';const parts=Object.fromEntries(beijingTime.formatToParts(date).map(p=>[p.type,p.value]));return `${Number(parts.month)} 月 ${Number(parts.day)} 日 ${parts.hour}:${parts.minute}（北京时间）`;};
export const links=urls=>urls.filter(safeURL).map((u,n)=>`<a href="${esc(safeURL(u))}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).hostname)}${n?' · '+(n+1):''} ↗</a>`).join('');
export function itemHTML(i,n=0,hero=false){return `<article class="${hero?'hero':'news-row'}" data-item="${esc(i.event_id)}">${hero?'':`<span class="number">${String(n+1).padStart(2,'0')}</span>`}<div>${hero?'<div class="eyebrow">本期重点</div>':''}<${hero?'h2':'h3'}>${esc(i.title)}</${hero?'h2':'h3'}><p>${esc(i.summary)}</p><div class="row-meta"><span class="tag">${esc(i.groupLabel)}</span>${stamp(i.event_at)?`<span>事件时间 ${esc(stamp(i.event_at))}</span>`:''}</div><div class="evidence">${links(i.urls)}</div></div></article>`}
export function offerHTML(o){return `<article class="column-card"><h3>${esc(o.provider)}</h3><p>${esc(o.kindLabel)}</p>${/unverified|partial|auto_only|availability_not_tested/.test(o.status)?'<p class="notice">核验边界：免费计划或政策有官方依据，但具体型号、额度或当前可用性仍有未确认项；请勿按确定可领权益预算。</p>':''}${o.models.length?`<ul class="model-list">${o.models.map(m=>`<li>${esc(m)}</li>`).join('')}</ul>`:'<p>未核实可单独选择的免费模型，不承诺全模型免费。</p>'}${(o.other_models||[]).map(g=>`<p>${esc(g.names.join('、'))}：${esc(g.quota)}</p>`).join('')}<p>额度：${esc(o.quota)}</p>${['conditions','expiry','privacy','caution'].filter(k=>o[k]).map(k=>`<p>${({conditions:'条件',expiry:'有效期',privacy:'隐私',caution:'注意'})[k]}：${esc(o[k])}</p>`).join('')}<div class="evidence">${links(o.sources)}</div></article>`}
export function matches(i,q,group='all'){return(group==='all'||i.group===group)&&(!q||JSON.stringify(i).toLowerCase().includes(q.toLowerCase().trim()))}
